      backup_text =
        "#HazelHtml Full App Example: a night garden almanac#\n\
         #Elm-style architecture with tabs, forms, commands, and subscriptions#\n\
         #msg = Msg sum type, model = (active_tab=String, form_name=String, \
         form_message=String, saved_message=String)#\n\n\
         type Msg =\n\
        \  + Tab(String)\n\
        \  + Name(String)\n\
        \  + Message(String)\n\
        \  + Submit\n\
         in\n\n\
         let init = (active_tab=\"Grove\", form_name=\"\", form_message=\"\", \
         saved_message=\"\") in\n\n\
         let update(msg, model) =\n\
        \  case msg\n\
        \  | Tab(tab) =>\n\
        \      ((active_tab=tab, form_name=model.form_name, \
         form_message=model.form_message, saved_message=model.saved_message),\n\
        \       CmdNone)\n\
        \  | Name(name) =>\n\
        \      ((active_tab=model.active_tab, form_name=name, \
         form_message=model.form_message, saved_message=model.saved_message),\n\
        \       CmdNone)\n\
        \  | Message(text) =>\n\
        \      ((active_tab=model.active_tab, form_name=model.form_name, \
         form_message=text, saved_message=model.saved_message),\n\
        \       CmdNone)\n\
        \  | Submit =>\n\
        \      let new_saved = model.form_name ++ \": \" ++ model.form_message \
         in\n\
        \      ((active_tab=model.active_tab, form_name=\"\", \
         form_message=\"\", saved_message=new_saved),\n\
        \       CmdBatch([Log(\"Note left: \" ++ new_saved), \
         Focus(\"name-input\")]))\n\
        \  end\n\
         in\n\n\
         let view(model) =\n\
        \  let tabs : [String] = [\"Grove\", \"Notes\", \"About\"] in\n\
        \  Div(\n\
        \    [\n\
        \      Id(\"app\"),\n\
        \      Style([\n\
        \        (\"max-width\", \"500px\"),\n\
        \        (\"margin\", \"20px auto\"),\n\
        \        (\"font-family\", \"Arial, sans-serif\"),\n\
        \        (\"border\", \"1px solid #ddd\"),\n\
        \        (\"border-radius\", \"8px\"),\n\
        \        (\"overflow\", \"hidden\")\n\
        \      ])\n\
        \    ],\n\
        \    [\n\
        \      #Header with tabs#\n\
        \      Div(\n\
        \        [Style([(\"display\", \"flex\"), (\"background\", \"#333\")])],\n\
        \        map(tabs, fun tab ->\n\
        \          Button(\n\
        \            [\n\
        \              OnClick(Tab(tab)),\n\
        \              Style([\n\
        \                (\"flex\", \"1\"),\n\
        \                (\"padding\", \"15px\"),\n\
        \                (\"border\", \"none\"),\n\
        \                (\"background\", if tab == model.active_tab then \
         \"#4CAF50\" else \"#333\"),\n\
        \                (\"color\", \"white\"),\n\
        \                (\"cursor\", \"pointer\"),\n\
        \                (\"font-size\", \"14px\")\n\
        \              ])\n\
        \            ],\n\
        \            [Text(tab)]\n\
        \          )\n\
        \        )\n\
        \      ),\n\
        \      #Content area#\n\
        \      Div(\n\
        \        [Style([(\"padding\", \"20px\"), (\"min-height\", \
         \"200px\")])],\n\
        \        [\n\
        \          if model.active_tab == \"Grove\" then\n\
        \            Div([], [\n\
        \              H2([], [Text(\"Welcome to the Night Garden!\")]),\n\
        \              P([], [Text(\"An almanac for the moonlit beds, showing \
         off:\")]),\n\
        \              Ul([], [\n\
        \                Li([], [Text(\"Tab navigation\")]),\n\
        \                Li([], [Text(\"Form handling with OnInput\")]),\n\
        \                Li([], [Text(\"Commands (Focus, Log)\")]),\n\
        \                Li([], [Text(\"Responsive styling\")])\n\
        \              ]),\n\
        \              if model.saved_message != \"\" then\n\
        \                Div(\n\
        \                  [Style([(\"background\", \"#e8f5e9\"), \
         (\"padding\", \"10px\"), (\"margin-top\", \"20px\"), \
         (\"border-radius\", \"4px\")])],\n\
        \                  [Text(\"Last note: \" ++ model.saved_message)]\n\
        \                )\n\
        \              else\n\
        \                Div([], [])\n\
        \            ])\n\
        \          else if model.active_tab == \"Notes\" then\n\
        \            Div([], [\n\
        \              H2([], [Text(\"Gardener's Notes\")]),\n\
        \              Div(\n\
        \                [Style([(\"margin-bottom\", \"15px\")])],\n\
        \                [\n\
        \                  Label([Style([(\"display\", \"block\"), \
         (\"margin-bottom\", \"5px\")])], [Text(\"Gardener:\")]),\n\
        \                  Input([\n\
        \                    Id(\"name-input\"),\n\
        \                    Type(\"text\"),\n\
        \                    Value(model.form_name),\n\
        \                    Placeholder(\"Who tended the beds?\"),\n\
        \                    OnInput(fun value -> Name(value)),\n\
        \                    Style([(\"width\", \"100%\"), (\"padding\", \
         \"8px\"), (\"box-sizing\", \"border-box\")])\n\
        \                  ])\n\
        \                ]\n\
        \              ),\n\
        \              Div(\n\
        \                [Style([(\"margin-bottom\", \"15px\")])],\n\
        \                [\n\
        \                  Label([Style([(\"display\", \"block\"), \
         (\"margin-bottom\", \"5px\")])], [Text(\"Note:\")]),\n\
        \                  TextArea(\n\
        \                    [\n\
        \                      Value(model.form_message),\n\
        \                      Placeholder(\"What did you plant tonight?\"),\n\
        \                      OnInput(fun value -> Message(value)),\n\
        \                      Style([(\"width\", \"100%\"), (\"padding\", \
         \"8px\"), (\"height\", \"100px\"), (\"box-sizing\", \"border-box\")])\n\
        \                    ],\n\
        \                    model.form_message\n\
        \                  )\n\
        \                ]\n\
        \              ),\n\
        \              Button(\n\
        \                [\n\
        \                  OnClick(Submit),\n\
        \                  Style([\n\
        \                    (\"background\", \"#4CAF50\"),\n\
        \                    (\"color\", \"white\"),\n\
        \                    (\"padding\", \"10px 20px\"),\n\
        \                    (\"border\", \"none\"),\n\
        \                    (\"cursor\", \"pointer\"),\n\
        \                    (\"border-radius\", \"4px\")\n\
        \                  ])\n\
        \                ],\n\
        \                [Text(\"Leave Note\")]\n\
        \              )\n\
        \            ])\n\
        \          else\n\
        \            Div([], [\n\
        \              H2([], [Text(\"About HazelHtml\")]),\n\
        \              P([], [Text(\"HazelHtml is a web app library for \
         Hazel.\")]),\n\
        \              Ul([], [\n\
        \                Li([], [Text(\"HTML element types (Div, Button, \
         Input, etc.)\")]),\n\
        \                Li([], [Text(\"Attribute types (Class, Style, \
         OnClick, etc.)\")]),\n\
        \                Li([], [Text(\"Command types (Focus, Delay, Log, \
         etc.)\")]),\n\
        \                Li([], [Text(\"Subscription types (OnResize, Every, \
         etc.)\")])\n\
        \              ])\n\
        \            ])\n\
        \        ]\n\
        \      ),\n\
        \      #Footer#\n\
        \      Div(\n\
        \        [Style([(\"background\", \"#f5f5f5\"), (\"padding\", \
         \"10px\"), (\"text-align\", \"center\"), (\"color\", \"#666\"), \
         (\"font-size\", \"12px\")])],\n\
        \        [Text(\"Built with HazelHtml, under a full moon\")]\n\
        \      )\n\
        \    ]\n\
        \  )\n\
         in\n\n\
         let subs(_model) = SubNone in\n\n\
         # Tests #\n\n\
         hint \"tab switch\"\n\
         test\n\
        \  let (m, _cmd) = update(Tab(\"Notes\"), init) in\n\
        \  m.active_tab == \"Notes\"\n\
         end;\n\n\
         hint \"name input\"\n\
         test\n\
        \  let (m, _cmd) = update(Name(\"Wren\"), init) in\n\
        \  m.form_name == \"Wren\"\n\
         end;\n\n\
         hint \"message input\"\n\
         test\n\
        \  let (m, _cmd) = update(Message(\"Sowed starfruit\"), init) in\n\
        \  m.form_message == \"Sowed starfruit\"\n\
         end;\n\n\
         hint \"submit clears form and saves\"\n\
         test\n\
        \  let filled = (active_tab=\"Notes\", form_name=\"Wren\", \
         form_message=\"Sowed starfruit\", saved_message=\"\") in\n\
        \  let (m, _cmd) = update(Submit, filled) in\n\
        \  m.form_name == \"\" && m.form_message == \"\" && m.saved_message == \
         \"Wren: Sowed starfruit\"\n\
         end;\n\n\
         hint \"tab preserves form data\"\n\
         test\n\
        \  let (filled, _) = update(Name(\"Wren\"), init) in\n\
        \  let (m, _cmd) = update(Tab(\"About\"), filled) in\n\
        \  m.form_name == \"Wren\"\n\
         end;\n\n\
         (init, update, view, subs)\n";
      refractors = "()";
    } )
